mapper.insert:
INSERT INTO job (
    job_name, plugin_id, cron_expression, job_status, misfire_policy, concurrent,
    input_json, timeout_millis, executed_status, remark, created_by, updated_by
) VALUES (
    #{jobName}, #{pluginId}, #{cronExpression}, #{jobStatus}, #{misfirePolicy}, #{concurrent},
    CAST(#{inputJson} AS JSON), #{timeoutMillis}, #{executedStatus}, #{remark}, #{actor}, #{actor}
)

mapper.select:
SELECT COUNT(*)
FROM job
WHERE plugin_id = #{pluginId}

SELECT COUNT(*)
FROM job
WHERE job_status = #{status}

mapper.update:
UPDATE job
SET executed_status = #{runningStatus}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND executed_status = #{idleStatus}

UPDATE job
SET executed_status = #{idleStatus}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND executed_status = #{runningStatus}
